  <style>
    /* ─── Design Tokens ─────────────────────────────── */
    :root {
      --green:        #2D6A4F;
      --green-light:  #40916C;
      --green-dark:   #1B4332;
      --green-pale:   #D8F3DC;
      --orange:       #F4A261;
      --orange-dark:  #E76F51;
      --cream:        #FEFAE0;
      --cream-dark:   #F5EFC8;
      --yellow:       #F9C74F;
      --terracotta:   #E07A5F;
      --teal:         #52B69A;
      --text-dark:    #1C2B20;
      --text-mid:     #4A6055;
      --text-light:   #7A9088;
      --white:        #FFFFFF;
      --shadow-sm:    0 2px 10px rgba(45,106,79,.10);
      --shadow-md:    0 6px 24px rgba(45,106,79,.14);
      --shadow-lg:    0 12px 48px rgba(45,106,79,.18);
      --shadow-xl:    0 20px 64px rgba(45,106,79,.22);
      --radius-xs:    8px;
      --radius-sm:    14px;
      --radius-md:    20px;
      --radius-lg:    28px;
      --radius-xl:    40px;
      --font-head:    'Nunito', sans-serif;
      --font-body:    'Inter', sans-serif;
      --transition:   0.25s ease;
    }

    /* ─── Reset ──────────────────────────────────────── */
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
    html { scroll-behavior: smooth; }
    body {
      font-family: var(--font-body);
      background: var(--cream);
      color: var(--text-dark);
      line-height: 1.65;
      overflow-x: hidden;
    }
    img { max-width: 100%; display: block; }
    a { text-decoration: none; color: inherit; }
    ul { list-style: none; }
    button { cursor: pointer; border: none; background: none; font-family: inherit; }

    /* ─── Layout ─────────────────────────────────────── */
    .container {
      max-width: 1200px;
      margin: 0 auto;
      padding: 0 24px;
    }
    .section {
      padding: 88px 0;
    }

    /* ─── Buttons ────────────────────────────────────── */
    .btn {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: 8px;
      font-family: var(--font-head);
      font-weight: 700;
      border-radius: 100px;
      transition: all var(--transition);
      white-space: nowrap;
    }
    .btn-primary {
      background: var(--green);
      color: var(--white);
      padding: 14px 28px;
      font-size: 15px;
    }
    .btn-primary:hover {
      background: var(--green-dark);
      transform: translateY(-2px);
      box-shadow: 0 8px 24px rgba(45,106,79,.30);
    }
    .btn-primary:active { transform: translateY(0); }
    .btn-outline {
      background: transparent;
      color: var(--green);
      border: 2px solid var(--green);
      padding: 12px 26px;
      font-size: 15px;
    }
    .btn-outline:hover {
      background: var(--green-pale);
      transform: translateY(-2px);
    }
    .btn-orange {
      background: var(--orange);
      color: var(--white);
      padding: 14px 28px;
      font-size: 15px;
    }
    .btn-orange:hover {
      background: var(--orange-dark);
      transform: translateY(-2px);
      box-shadow: 0 8px 24px rgba(244,162,97,.35);
    }
    .btn-lg { padding: 16px 36px; font-size: 16px; }
    .btn-sm { padding: 10px 20px; font-size: 13px; }

    /* ─── Section Header ─────────────────────────────── */
    .section-tag {
      display: inline-block;
      background: var(--green-pale);
      color: var(--green);
      font-family: var(--font-head);
      font-weight: 700;
      font-size: 12px;
      letter-spacing: .08em;
      text-transform: uppercase;
      padding: 6px 16px;
      border-radius: 100px;
      margin-bottom: 14px;
    }
    .section-header {
      text-align: center;
      max-width: 600px;
      margin: 0 auto 56px;
    }
    .section-header h2 {
      font-family: var(--font-head);
      font-size: clamp(28px, 4vw, 42px);
      font-weight: 800;
      color: var(--text-dark);
      margin-bottom: 16px;
    }
    .section-header p {
      font-size: 17px;
      color: var(--text-mid);
      line-height: 1.7;
    }

    /* ─── HEADER ─────────────────────────────────────── */
    .header {
      position: sticky;
      top: 0;
      z-index: 100;
      background: rgba(254,250,224,.92);
      backdrop-filter: blur(16px);
      -webkit-backdrop-filter: blur(16px);
      border-bottom: 1px solid transparent;
      transition: border-color var(--transition), box-shadow var(--transition);
    }
    .header.scrolled {
      border-color: rgba(45,106,79,.12);
      box-shadow: 0 2px 20px rgba(45,106,79,.10);
    }
    .nav {
      display: flex;
      align-items: center;
      height: 72px;
      gap: 40px;
    }
    .logo {
      display: flex;
      align-items: center;
      gap: 10px;
      flex-shrink: 0;
    }
    .logo-icon {
      font-size: 26px;
      line-height: 1;
    }
    .logo-text {
      font-family: var(--font-head);
      font-size: 20px;
      font-weight: 600;
      color: var(--text-dark);
    }
    .logo-text strong {
      color: var(--green);
      font-weight: 900;
    }
    .nav-links {
      display: flex;
      align-items: center;
      gap: 4px;
      flex: 1;
    }
    .nav-links li a {
      font-family: var(--font-head);
      font-weight: 600;
      font-size: 15px;
      color: var(--text-mid);
      padding: 8px 14px;
      border-radius: var(--radius-xs);
      transition: color var(--transition), background var(--transition);
    }
    .nav-links li a:hover {
      color: var(--green);
      background: var(--green-pale);
    }
    .hamburger {
      display: none;
      flex-direction: column;
      gap: 5px;
      padding: 8px;
      margin-left: auto;
    }
    .hamburger span {
      display: block;
      width: 22px;
      height: 2px;
      background: var(--text-dark);
      border-radius: 2px;
      transition: all var(--transition);
    }
    .mobile-nav {
      display: none;
      background: var(--cream);
      border-top: 1px solid rgba(45,106,79,.10);
      padding: 16px 24px 24px;
    }
    .mobile-nav.open { display: block; }
    .mobile-nav ul { display: flex; flex-direction: column; gap: 4px; }
    .mobile-nav ul li a {
      display: block;
      font-family: var(--font-head);
      font-weight: 600;
      font-size: 16px;
      color: var(--text-mid);
      padding: 12px 16px;
      border-radius: var(--radius-xs);
      transition: all var(--transition);
    }
    .mobile-nav ul li a:hover { color: var(--green); background: var(--green-pale); }

    /* ─── HERO ───────────────────────────────────────── */
    .hero {
      padding: 80px 0 96px;
      overflow: hidden;
      position: relative;
      background: linear-gradient(135deg, var(--cream) 0%, #F0F7EF 100%);
    }
    .hero::before {
      content: '';
      position: absolute;
      top: -120px; right: -120px;
      width: 500px; height: 500px;
      background: radial-gradient(circle, rgba(64,145,108,.12) 0%, transparent 70%);
      border-radius: 50%;
      pointer-events: none;
    }
    .hero::after {
      content: '';
      position: absolute;
      bottom: -80px; left: -80px;
      width: 380px; height: 380px;
      background: radial-gradient(circle, rgba(244,162,97,.10) 0%, transparent 70%);
      border-radius: 50%;
      pointer-events: none;
    }
    .hero .container {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 64px;
      align-items: center;
    }
    .hero-badge {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      background: var(--white);
      border: 1.5px solid var(--green-pale);
      color: var(--green);
      font-family: var(--font-head);
      font-weight: 700;
      font-size: 13px;
      padding: 7px 16px;
      border-radius: 100px;
      box-shadow: var(--shadow-sm);
      margin-bottom: 24px;
    }
    .hero h1 {
      font-family: var(--font-head);
      font-size: clamp(36px, 5vw, 58px);
      font-weight: 900;
      line-height: 1.1;
      color: var(--text-dark);
      margin-bottom: 22px;
    }
    .hero h1 em {
      font-style: normal;
      color: var(--green);
      position: relative;
    }
    .hero h1 em::after {
      content: '';
      position: absolute;
      bottom: 2px; left: 0; right: 0;
      height: 6px;
      background: var(--yellow);
      border-radius: 3px;
      z-index: -1;
      opacity: .5;
    }
    .hero-content > p {
      font-size: 18px;
      color: var(--text-mid);
      line-height: 1.75;
      margin-bottom: 36px;
      max-width: 480px;
    }
    .hero-actions {
      display: flex;
      flex-wrap: wrap;
      gap: 14px;
      margin-bottom: 40px;
    }
    .hero-stats {
      display: flex;
      align-items: center;
      gap: 20px;
      flex-wrap: wrap;
    }
    .hero-stat {
      font-family: var(--font-head);
      font-size: 14px;
      color: var(--text-mid);
    }
    .hero-stat strong {
      display: block;
      font-size: 20px;
      font-weight: 900;
      color: var(--green);
    }
    .hero-stat-divider {
      width: 1px;
      height: 32px;
      background: rgba(45,106,79,.20);
    }

    /* Hero Visual */
    .hero-visual {
      display: flex;
      justify-content: center;
      align-items: center;
    }
    .hero-food-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 16px;
      width: 100%;
      max-width: 380px;
    }
    .food-card {
      background: var(--white);
      border-radius: var(--radius-md);
      box-shadow: var(--shadow-md);
      aspect-ratio: 1;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 52px;
      transition: transform var(--transition), box-shadow var(--transition);
      animation: float-gentle 4s ease-in-out infinite;
    }
    .food-card:nth-child(1) { animation-delay: 0s; }
    .food-card:nth-child(2) { animation-delay: .5s; }
    .food-card:nth-child(3) { animation-delay: 1s; }
    .food-card:nth-child(4) { animation-delay: 1.5s; }
    .food-card:nth-child(5) { animation-delay: 2s; }
    .food-card:nth-child(6) { animation-delay: 2.5s; }
    .food-card:hover {
      transform: translateY(-6px) scale(1.06);
      box-shadow: var(--shadow-lg);
    }
    @keyframes float-gentle {
      0%, 100% { transform: translateY(0); }
      50% { transform: translateY(-8px); }
    }

    /* ─── FEATURED PRODUCTS ──────────────────────────── */
    .featured-products {
      background: var(--white);
    }
    .carousel-wrapper {
      position: relative;
      display: flex;
      align-items: center;
      gap: 12px;
    }
    .carousel-viewport {
      flex: 1;
      overflow: hidden;
      border-radius: var(--radius-md);
    }
    .carousel-track {
      display: flex;
      gap: 20px;
      transition: transform 0.45s cubic-bezier(0.4, 0, 0.2, 1);
      will-change: transform;
    }
    .product-card {
      flex: 0 0 calc(25% - 15px);
      background: var(--cream);
      border-radius: var(--radius-md);
      overflow: hidden;
      box-shadow: var(--shadow-sm);
      transition: transform var(--transition), box-shadow var(--transition);
      border: 1.5px solid transparent;
    }
    .product-card:hover {
      transform: translateY(-4px);
      box-shadow: var(--shadow-md);
      border-color: var(--green-pale);
    }
    .product-img {
      height: 160px;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 64px;
      position: relative;
      overflow: hidden;
    }
    .product-body {
      padding: 16px 18px 20px;
    }
    .product-name {
      font-family: var(--font-head);
      font-weight: 800;
      font-size: 15px;
      color: var(--text-dark);
      margin-bottom: 6px;
      line-height: 1.3;
    }
    .product-desc {
      font-size: 13px;
      color: var(--text-light);
      line-height: 1.5;
      margin-bottom: 14px;
    }
    .product-footer {
      display: flex;
      align-items: center;
      justify-content: space-between;
    }
    .product-price {
      font-family: var(--font-head);
      font-weight: 900;
      font-size: 18px;
      color: var(--green);
    }
    .product-add {
      width: 34px; height: 34px;
      background: var(--green);
      color: var(--white);
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 20px;
      font-weight: 400;
      line-height: 1;
      transition: all var(--transition);
      cursor: pointer;
    }
    .product-add:hover {
      background: var(--green-dark);
      transform: scale(1.1) rotate(90deg);
    }

    .carousel-btn {
      flex-shrink: 0;
      width: 48px; height: 48px;
      background: var(--white);
      border: 2px solid var(--green-pale);
      border-radius: 50%;
      font-size: 22px;
      color: var(--green);
      display: flex;
      align-items: center;
      justify-content: center;
      box-shadow: var(--shadow-sm);
      transition: all var(--transition);
      z-index: 2;
      line-height: 1;
    }
    .carousel-btn:hover:not(:disabled) {
      background: var(--green);
      color: var(--white);
      border-color: var(--green);
      box-shadow: var(--shadow-md);
      transform: scale(1.08);
    }
    .carousel-btn:disabled { opacity: .35; cursor: not-allowed; }
    .carousel-dots {
      display: flex;
      justify-content: center;
      gap: 8px;
      margin-top: 28px;
    }
    .carousel-dot {
      width: 8px; height: 8px;
      border-radius: 50%;
      background: var(--green-pale);
      border: none;
      cursor: pointer;
      transition: all var(--transition);
    }
    .carousel-dot.active {
      background: var(--green);
      width: 24px;
      border-radius: 4px;
    }

    /* ─── BRAND HIGHLIGHTS ───────────────────────────── */
    .highlights-banner {
      background: linear-gradient(135deg, var(--green-dark) 0%, var(--green) 100%);
      padding: 64px 0;
      position: relative;
      overflow: hidden;
    }
    .highlights-banner::before {
      content: '';
      position: absolute;
      top: -100px; right: -100px;
      width: 400px; height: 400px;
      background: rgba(255,255,255,.04);
      border-radius: 50%;
    }
    .highlights-banner::after {
      content: '';
      position: absolute;
      bottom: -80px; left: -80px;
      width: 320px; height: 320px;
      background: rgba(255,255,255,.04);
      border-radius: 50%;
    }
    .highlights-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 0;
      text-align: center;
    }
    .highlight-item {
      padding: 20px 24px;
      border-right: 1px solid rgba(255,255,255,.15);
      position: relative;
      z-index: 1;
    }
    .highlight-item:last-child { border-right: none; }
    .highlight-num {
      display: block;
      font-family: var(--font-head);
      font-size: clamp(36px, 4vw, 52px);
      font-weight: 900;
      color: var(--yellow);
      line-height: 1;
      margin-bottom: 8px;
    }
    .highlight-label {
      display: block;
      font-family: var(--font-head);
      font-weight: 800;
      font-size: 16px;
      color: var(--white);
      margin-bottom: 8px;
    }
    .highlight-desc {
      display: block;
      font-size: 13px;
      color: rgba(255,255,255,.68);
      line-height: 1.5;
    }

    /* ─── SEASONAL PICKS ─────────────────────────────── */
    .seasonal-picks {
      background: var(--cream);
    }
    .seasonal-tag {
      display: inline-block;
      background: linear-gradient(135deg, var(--orange), var(--yellow));
      color: var(--white);
      font-family: var(--font-head);
      font-weight: 700;
      font-size: 12px;
      letter-spacing: .08em;
      text-transform: uppercase;
      padding: 6px 16px;
      border-radius: 100px;
      margin-bottom: 14px;
    }
    .seasonal-grid {
      display: grid;
      grid-template-columns: repeat(2, 1fr);
      gap: 20px;
    }
    .seasonal-card {
      background: var(--white);
      border-radius: var(--radius-md);
      padding: 28px;
      display: flex;
      gap: 20px;
      align-items: flex-start;
      box-shadow: var(--shadow-sm);
      border: 1.5px solid transparent;
      transition: all var(--transition);
    }
    .seasonal-card:hover {
      transform: translateY(-3px);
      box-shadow: var(--shadow-md);
      border-color: rgba(244,162,97,.25);
    }
    .seasonal-emoji {
      font-size: 48px;
      flex-shrink: 0;
      width: 72px; height: 72px;
      background: var(--cream);
      border-radius: var(--radius-sm);
      display: flex;
      align-items: center;
      justify-content: center;
    }
    .seasonal-info { flex: 1; }
    .seasonal-badge {
      display: inline-block;
      background: rgba(244,162,97,.15);
      color: var(--orange-dark);
      font-family: var(--font-head);
      font-weight: 700;
      font-size: 11px;
      letter-spacing: .06em;
      text-transform: uppercase;
      padding: 3px 10px;
      border-radius: 100px;
      margin-bottom: 10px;
    }
    .seasonal-name {
      font-family: var(--font-head);
      font-weight: 800;
      font-size: 16px;
      color: var(--text-dark);
      margin-bottom: 6px;
    }
    .seasonal-desc {
      font-size: 13px;
      color: var(--text-light);
      line-height: 1.5;
      margin-bottom: 14px;
    }
    .seasonal-price {
      font-family: var(--font-head);
      font-weight: 900;
      font-size: 20px;
      color: var(--orange-dark);
    }

    /* ─── CATEGORIES ─────────────────────────────────── */
    .categories {
      background: var(--white);
    }
    .categories-grid {
      display: grid;
      grid-template-columns: repeat(5, 1fr);
      gap: 16px;
    }
    .category-card {
      position: relative;
      border-radius: var(--radius-md);
      overflow: hidden;
      aspect-ratio: .85;
      cursor: pointer;
      box-shadow: var(--shadow-sm);
      transition: box-shadow var(--transition);
