    .store-card {
      background: var(--white);
      border-radius: var(--radius-md);
      padding: 22px 24px;
      display: flex;
      align-items: center;
      gap: 16px;
      margin-bottom: 12px;
      box-shadow: var(--shadow-sm);
      border: 1.5px solid var(--green-pale);
      text-align: left;
      transition: all var(--transition);
      animation: slide-in .35s ease forwards;
      opacity: 0;
